---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'div'> {}

const { class: className, ...props } = Astro.props;
---

<div class={cn('relative inline-block', className)} data-popover {...props}>
  <slot />
</div>

<script>
  import { registerUiInit } from "@/utils/runtime/loader";
  import { initPopovers } from "@/utils/runtime/popover";
  import { initDisclosureTriggers } from "@/utils/runtime/disclosure-triggers";

  registerUiInit(initPopovers);
  registerUiInit(initDisclosureTriggers);
</script>

---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'div'> {
  align?: 'start' | 'center' | 'end';
  side?: 'top' | 'right' | 'bottom' | 'left';
  id?: string | null;
}

const {
  align = 'center',
  side = 'bottom',
  class: className,
  id,
  ...props
} = Astro.props;

const contentId = id ?? undefined;

const classes = cn(
  'z-50 w-72 rounded-lg border bg-popover p-4 text-popover-foreground shadow-md outline-none',
  className
);
---

<div
  class={classes}
  data-popover-content
  data-side={side}
  data-align={align}
  role="dialog"
  aria-modal="false"
  id={contentId}
  hidden
  {...props}
>
  <slot />
</div>

---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'span'> {}

const { class: className, ...props } = Astro.props;
---

<span
  class={cn('inline-block cursor-pointer', className)}
  data-popover-trigger
  role="button"
  tabindex="0"
  aria-expanded="false"
  {...props}
>
  <slot />
</span>

<script>
  import { registerUiInit } from "@/utils/runtime/loader";
  import { initPopovers } from "@/utils/runtime/popover";
  import { initDisclosureTriggers } from "@/utils/runtime/disclosure-triggers";

  registerUiInit(initPopovers);
  registerUiInit(initDisclosureTriggers);
</script>
